  (* [comment removed for export] *)
  Lemma sy_loop : forall f s n i syms position r m1 (x31 : word),
    sym_loop tl f i n s syms position hT = Ok r ->
    0 <= i < n -> n < 2^31 -> 0 <= s < 256 -> 0 <= position < 2^tl -> length syms = Z.to_nat (2^tl) ->
    gn_inv m1 syms ->
    (forall m2 syms' p' (y30 y31 : word), r = (syms', p') -> 0 <= p' < 2^tl -> length syms' = Z.to_nat (2^tl) ->
       gn_inv m2 syms' ->
       evt psegs POST (ST 0x1ba9c m2 (Z_to_bv 64 p') (Z_to_bv 64 s) (Z_to_bv 64 n) y30 y31)) ->
    evt psegs POST (ST 0x1bab8 m1 (Z_to_bv 64 position) (Z_to_bv 64 s) (Z_to_bv 64 n) (Z_to_bv 64 i) x31).
