  Lemma gn_loop : forall f s syms position r m1 (x29 x30 x31 : word),
    gen_loop nc tl f s syms position hT = Ok r ->
    Z.of_nat f = M1 - s -> 0 <= s < M1 -> 0 <= position < 2^tl -> length syms = Z.to_nat (2^tl) ->
